    //统一定制角色资料格式的代码
    var createIntro = function (des, sj, bc, py, tc) {
        var pre = '<img style=width:600px src=';
        var path = 'extension/金庸群侠传/image/label/';
        var png = '.png><br>';
        var bl = '<br><br>';
        var peh = pre + path;
        return peh + 'xz' + png + '&nbsp;&nbsp;&nbsp;&nbsp;' + des + bl + peh + 'sj' + png + sj + bl + peh + 'bc' + png + bc + bl + peh + 'py' + png + py + bl + peh + 'tc' + png + tc;
    };
    //createIntro("暂无武将描述","大小熊猫","落影","稳得高处","暂无台词");
    var createTaici = function (tc) {
        var pre = '<img style=width:28px src=';
        var path = 'extension/金庸群侠传/image/xingji/';
        var png2 = 'line2.png><font size = 20px>';
        var inn = '</font>';
        var pre2 = '<img style=width:248px src=';
        var png = 'line1.png>';
        var bl = '<br><br>';
        var peh = pre + path + png2;
        var peh2 = inn + pre2 + path + png;
        var cob = function (sy) {
            return peh + sy[0] + peh2 + sy[1];
        };
        tc = tc.replace(/<b>【/g, '#');
        tc = tc.replace(/】<\/b>/g, '@');
        var arr = tc.split('#');
        if (arr[0] == '') arr.splice(0, 1);
        var str = '';
        for (var i = 0; i < arr.length; i++) {
            var arr2 = arr[i].split('@');
            str += cob([arr2[0], arr2[1]]);
        }
        return str + bl;
    };
    //"ywhy_boya":createTaici("<b>【摄命】</b><br>无敌旋风，夺魂索命！<br>草菅人命，法不容情！<br><br><b>【追踪】</b><br>尔等宵小之辈，哪里逃！<br>你已死路一条，还不束手伏法？<br><br><b>【阵亡】</b><br>得之我幸，失之我命……"),
