        qtpz_weihutou: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_xuanye: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_chenjinnan: createGonglue(3, 4, 4, 3, '陈近南是一名控场类武将，同时还能掉血将队友使用的AOE牌再次给队友，组成小绝情阵，自己还有有小过牌。适合当护法或刺客。', '对敌人发动凝血时，对让其限入两难的抉择，无论掉不掉血都比较难受，下个回合将被封印一种类别的牌。如果你是陈近南的队友，你可以大胆地放鞑虏入侵等，他有可能助你一扫全场。', '陈近南的关键牌是杀和队友的AOE，和能够获得AOE的队友是最佳拍档。'),
        qtpz_jianninggongzhu: createGonglue(3, 4, 4, 4, '建宁公主的技能综合能力较全面，能过牌、能拆牌、能配合队友转化牌、还能转化延时锦囊牌，全身份适应 。 ', '建宁公主的欲孽可以在队友的配合下转化关键牌，同时辅助队友过牌；也可以用来拆敌方的牌；同时，还可以在队友有负面延时锦囊牌的情况下用来帮队友拆除隔空点穴等。违诏是一个收益较大的技能，因为金庸包里有正面延时锦囊牌如运功疗伤，作为建宁的敌方，建议放弃对她的团队使用延时锦囊牌，她可以全部转化为运功疗伤等，反而帮了她；也不要对你的队友用运功疗伤，她会转化为隔空点穴等，反而害了队友。', '建宁公主能配合或者克制所有能转化延时锦囊牌的角色，比如鸠摩智、桃谷六仙、吴应熊等。'),
        qtpz_fengjizhong: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_aobai: createGonglue(4, 4, 4, 3, '鳌拜本质上一个多刀流的菜刀，兼具一定的过牌能力，集攻防于一体，强度中规中矩。', '每轮可以捡一张杀来输出，所以见招拆招和隔空点穴是他的关键牌，队友也需要注意尽量在弃牌时弃一张杀来配合他发动摄政。如果你是他的敌人，谨慎对他使用比武和鞑虏入侵，有可能偷鸡不成蚀把米。', '鳌拜较克制或配合过牌大的角色，过牌大的侠客弃牌时弃置杀的几率更高，鳌拜更容易发动摄政。'),
        qtpz_haidafu: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_zengrou: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_hongantong: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_maodongzhu: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_shuanger: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_sangjielama: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        qtpz_wusangui: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        ldj_wuyingxiong: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        //笑傲江湖
        xajh_jiangnansiyou: createGonglue(3, 4, 5, 3, '江南四友是一名苟住爆发的瞬间打击破核的武将，但容易后继无力，适合目标明确的刺客身份。', '拥有四个限定技的江南四友，其每个技能之间或多或少也有千丝万缕的联动性。选择何时喝下越陈越香的珍酿酒至关重要，依局势而定，不能一概而论，如果是在持久局，你可以选择苟到中后期再饮酒，配合索链和属性杀，也许能打出一杀秒全场的骚操作。点睛和挥毫往往会联合起来同时发动，可以有机会瞬间破核甚至一路杀下去，如果你是江南四友的包养系队友，尽可能地将某个花色的杀送给他。对弈则是一个非常考验综合能力的技能，细说起来可以写到2000字，总之根据你想要该延时锦囊牌判定成功或失败，以及你的手牌花色结构再选择合适的对弈对象，小心别搬起石头砸了自己的脚。', '点睛可以配合暴力菜刀比如李小龙，带上半个咆哮的李小龙输出还是可观的，大部分情况下如果有人包养自己，点晴对自己发动是最适合的。'),
        xajh_sp_tianboguang: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
        xajh_liangfa: createGonglue(3, 3, 3, 3, '定位', '攻略', '生克'),
